'use strict';
const $=s=>document.querySelector(s),fmt=n=>Math.floor(n).toLocaleString();
const KEY='veilstorm-save-v1';
function uiIcon(n,cls=''){return `<i class="ui-icon ${cls}" aria-hidden="true" style="background-position:${n%4*100/3}% ${Math.floor(n/4)*100/3}%"></i>`}

const initial=()=>({name:'Miho',level:1,xp:0,coins:1200,hp:100,energy:60,stamina:20,atk:20,def:16,points:3,items:{},tech:{},team:[],missions:{},rivalHealth:{},wins:0,losses:0,kills:0,deaths:0,bank:0,last:Date.now(),activity:['Your journey in Hollow Falls begins.']});
let s;try{s={...initial(),...JSON.parse(localStorage.getItem(KEY)||'null')};}catch{s=initial()}let tab='arena',filter='all',busy=false;let lastResults={};
const techniques=GAME_CATALOG.jutsus;
const grades=GAME_CATALOG.grades;
let selectedGrades={missions:"E",techniques:"E"};
const items=[{id:'blade',name:'Moonsteel Blade',a:14,d:0,price:350,icon:'†',desc:'A balanced blade forged beneath the mountain.'},{id:'coat',name:'Warden’s Mantle',a:0,d:15,price:400,icon:'◈',desc:'Layered cloth reinforced with light iron plates.'},{id:'needles',name:'Storm Needles',a:9,d:3,price:260,icon:'✣',desc:'A set of finely weighted throwing needles.'},{id:'charm',name:'Riverstone Charm',a:4,d:9,price:300,icon:'◇',desc:'A polished talisman carried by Hollow Falls scouts.'}];
const companions=[{id:'ren',name:'Ren Ashfall',role:'Blade scout',a:24,d:16,price:450,face:1},{id:'kae',name:'Kae Emberwind',role:'Flame weaver',a:32,d:12,price:650,face:2},{id:'voss',name:'Voss Nightglass',role:'Veil guardian',a:18,d:36,price:800,face:3}];
const opponents=[{id:0,name:'Ren Ashfall',clan:'Wandering Blades',level:1,def:25,atk:22,team:1,face:1,coins:65,xp:18},{id:1,name:'Kae Emberwind',clan:'Ember Covenant',level:2,def:44,atk:35,team:2,face:2,coins:110,xp:27},{id:2,name:'Voss Nightglass',clan:'Order of the Veil',level:4,def:76,atk:62,team:3,face:3,coins:180,xp:40},{id:3,name:'The Hollow Warden',clan:'Guardian of the Falls',level:7,def:125,atk:105,team:4,face:3,coins:300,xp:65}];
const missions=GAME_CATALOG.missions;
function maxHealth(){return 100+(s.healthBonus||0)}
function maxEnergy(){return 60+(s.level-1)*5+s.team.length*5+(s.spiritBonus||0)}function maxStamina(){return 20+(s.level-1)*2+(s.staminaBonus||0)}function goal(){return s.level*80}function rank(){return s.level>=7?'Warden':s.level>=5?'Sentinel':s.level>=3?'Adept':'Initiate'}
function power(){let a=s.atk,d=s.def,ia=0,id=0,ta=0,td=0,ca=0,cd=0;items.forEach(x=>{if(s.items[x.id]){ia+=x.a;id+=x.d}});techniques.forEach(x=>{ta+=x.a*(s.tech[x.id]||0);td+=x.d*(s.tech[x.id]||0)});companions.forEach(x=>{if(s.team.includes(x.id)){ca+=Math.round(x.a*.3);cd+=Math.round(x.d*.3)}});return{a:a+ia+ta+ca,d:d+id+td+cd,ia,id,ta,td,ca,cd}}
function save(){try{localStorage.setItem(KEY,JSON.stringify(s));if(s.uid&&window.ShinobiFirestore){window.ShinobiFirestore.savePlayerData(s.uid,s).catch(e=>console.error('Cloud save failed:',e))}}catch{toast('Browser storage unavailable. Keep this tab open.')}}
function log(t){s.activity.unshift(t);s.activity=s.activity.slice(0,6)}function gain(xp,coins){s.xp+=xp;s.coins+=coins;while(s.xp>=goal()){s.xp-=goal();s.level++;s.points+=3;s.hp=maxHealth();s.energy=Math.max(s.energy,maxEnergy());s.stamina=maxStamina();log('Reached level '+s.level+' · 3 stat points earned.')}}
function rivalState(id){s.rivalHealth??={};return s.rivalHealth[id]??=( {hp:100,last:Date.now(),kills:0,deaths:0} )}
function regenRivals(){let changed=false;for(const r of Object.values(s.rivalHealth||{})){const n=Math.floor((Date.now()-r.last)/60000);if(n>0){r.hp=Math.min(100,r.hp+n*2);r.last+=n*60000;changed=true}}return changed}
function regen(){const rivalsChanged=regenRivals();if(rivalsChanged)save();let n=Math.floor((Date.now()-s.last)/60000);if(n>0){s.hp=Math.min(maxHealth(),s.hp+n*2);s.energy=s.energy>maxEnergy()?s.energy:Math.min(maxEnergy(),s.energy+n*3);s.stamina=Math.min(maxStamina(),s.stamina+n);s.last+=n*60000;save()}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function open(html){$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}function escapeHTML(t){return String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function title(h,p){return `<div class="page-title"><div class="eyebrow">THE SHATTERED PROVINCES</div><h1>${h}</h1><p>${p}</p></div>`}
function render(){regen();const p=power();$('#rank').textContent=rank()+' · Lv. '+s.level;$('.profile>span:last-child').innerHTML=escapeHTML(s.name)+`<small id="rank">${rank()} · Lv. ${s.level}</small>`;$('.player-art>span').innerHTML=escapeHTML(s.name.toUpperCase())+'<small>HOLLOW FALLS SHINOBI</small>';$('#player-level').textContent='Level '+s.level;$('#xp-label').textContent=s.xp+' / '+goal()+' XP';$('#xp-bar').style.width=(s.xp/goal()*100)+'%';$('#power-stats').innerHTML=`<div>${uiIcon(0)}<span>ATTACK<strong>${fmt(p.a)}</strong></span></div><div>${uiIcon(15)}<span>DEFENSE<strong>${fmt(p.d)}</strong></span></div><div>${uiIcon(4)}<span>TEAM<strong>${s.team.length}</strong></span></div><div>${uiIcon(10)}<span>VICTORIES<strong>${s.wins}</strong></span></div><div>${uiIcon(0)}<span>KILLS<strong>${s.kills}</strong></span></div><div>${uiIcon(7)}<span>DEATHS<strong>${s.deaths}</strong></span></div>`;
$('#resources').innerHTML=[[6,'Copper',fmt(s.coins),null,'bank'],[7,'Health',s.hp+' / '+maxHealth(),s.hp/maxHealth()*100,'heal'],[8,'Spirit',s.energy+' / '+maxEnergy(),s.energy/maxEnergy()*100,'rest'],[9,'Stamina',s.stamina+' / '+maxStamina(),s.stamina/maxStamina()*100,'rest'],[10,'Experience',s.xp+' / '+goal(),s.xp/goal()*100,null]].map(([icon,label,value,percent,action])=>`<div class="res"><span class="res-icon">${uiIcon(icon)}</span><span class="res-label">${label}</span><strong>${value}</strong>${action?`<button data-action="${action}" aria-label="${action==='bank'?'Open bank':action==='heal'?'Heal at infirmary':'Restore resources'}">+</button>`:''}${percent!==null?`<div class="bar"><i style="width:${percent}%;background:${label==='Health'?'#d07669':label==='Spirit'?'#70b8d7':label==='Experience'?'#ad8dde':'#d9b174'}"></i></div>`:''}</div>`).join('');
$('#nav').innerHTML=[['arena',0,'Fight','Battle arena'],['missions',1,'Missions','Province contracts'],['techniques',2,'Jutsus','Master your arts'],['equipment',3,'Equipment','The armory'],['team',4,'Your team','Trusted companions'],['profile',5,'Profile','Your legend'],['story',1,'Story','Province chronicles'],['duties',2,'Duties','Village service'],['council',15,'Council','Upgrades'],['gifts',8,'Gifts','Spirit packs'],['ranks',10,'Rankings','Local rivals'],['forum',4,'Forum','Village board']].map(([id,icon,name,sub])=>`<button data-tab="${id}" class="${tab===id?'active':''}" aria-current="${tab===id?'page':'false'}">${uiIcon(icon)}<span class="nav-copy"><b>${name}</b><small>${sub}</small></span></button>`).join('');$('.chapter>span').textContent='HOLLOW FALLS / '+({arena:'BATTLE ARENA',missions:'MISSION BOARD',techniques:'JUTSU HALL',equipment:'ARMORY',team:'YOUR TEAM',profile:'YOUR LEGEND',story:'STORY CHAPTERS',duties:'VILLAGE DUTIES',council:'VILLAGE COUNCIL',gifts:'GIFTS',ranks:'LOCAL RANKINGS',forum:'VILLAGE FORUM'}[tab]);$('#activity').innerHTML=s.activity.slice(0,3).map(x=>`<p>${escapeHTML(x)}</p>`).join('');({arena:arena,missions:missionView,techniques:techView,equipment:equipmentView,team:teamView,profile:profileView,...globalThis.extraViews}[tab])();renderResult();}
function arena(){const p=power();const rivals=opponents.filter(o=>filter==='all'||(filter==='matched'?o.def<=p.a*1.35:o.def>p.a*1.35));$('#view').innerHTML=`<div class="hero"><div class="eyebrow">HOLLOW FALLS · DUELING GROUNDS</div><h1>WALK THE PATH<br>OF A SHINOBI</h1><p>A sharp blade is only the beginning.<br>Train your arts. Rally your team. Rise.</p><span class="hero-stamp">BATTLE ARENA</span></div><div class="section-head"><div><h2>Choose your rival</h2><p>Test your strength against the province’s shinobi.</p></div><span class="badge">PRACTICE · AI RIVALS</span></div><div class="tabs"><button data-filter="all" class="${filter==='all'?'active':''}">All opponents</button><button data-filter="matched" class="${filter==='matched'?'active':''}">Within reach</button><button data-filter="elite" class="${filter==='elite'?'active':''}">Elite challenges</button></div>${rivals.length?rivals.map(o=>`<article class="opponent"><div class="portrait face f${o.face}"></div><div><h3>${o.name}</h3><div class="detail">Lv. ${o.level} · ${o.clan}</div><div class="rival-health"><span>${uiIcon(7)} ${rivalState(o.id).hp} / 100 HP${rivalState(o.id).hp===0?' · Recovering':''}</span><div class="bar"><i style="width:${rivalState(o.id).hp}%;background:#d07669"></i></div></div><div class="detail">${rivalState(o.id).kills||0} Kills · ${rivalState(o.id).deaths||0} Deaths</div><div class="numbers"><span>${uiIcon(15)} <b>${o.def}</b> defense</span><span>${uiIcon(4)} <b>${o.team}</b> team</span></div></div><div class="challenge"><div class="difficulty ${o.def>p.a*1.15?'hard':''}">${o.def<p.a*.8?'FAVORED':o.def<=p.a*1.15?'EVEN MATCH':'CHALLENGING'}</div><button class="gold" data-fight="${o.id}" ${s.stamina<1||s.hp<=0||rivalState(o.id).hp<=0||busy?'disabled':''}>${rivalState(o.id).hp<=0?'Recovering':'Fight'} <span class="button-cost">${uiIcon(9)} 1</span></button></div></article>`).join(''):'<div class="empty">No rivals in this category. Try another filter.</div>'}<div class="combat-note"><b>Every advantage counts.</b> Fights resolve automatically from your attack versus the rival’s defense, with a small variation. Techniques, equipped items, and 30% of your companions’ stats contribute. Each fight costs 1 stamina and deals at most 27 HP damage to each fighter. Rivals at 0 HP cannot be attacked until their health regenerates (2 HP per minute).</div>`}
function renderResult(){
 const r=lastResults[tab];if(!r)return;if(r.grade&&r.grade!==selectedGrades[tab])return;
 let body='',action='',disabled=false;
 if(r.type==='fight'){
  const o=opponents.find(x=>x.id===r.id);
  const equipment=r.equipment.length?r.equipment.join(', '):'No equipment';
  const arts=r.arts.length?r.arts.join(', '):'No learned techniques';
  body=`<h3 class="friendly">Your team of ${r.teamCount} shinobi fought against ${escapeHTML(o.name)} with:</h3><p>${equipment}<br>${arts}</p><p class="report-breakdown">Attack: ${r.base} base + ${r.gear} equipment + ${r.tech} techniques + ${r.team} team support.</p><h3 class="hostile">${escapeHTML(o.name)}’s team of ${o.team} shinobi defended:</h3><p>${o.clan} · ${o.def} total defense strength</p><p>Your total attack strength of <strong>${r.attack}</strong> ${r.won?'was enough':'was not enough'} against ${escapeHTML(o.name)}’s total defense strength of <strong>${o.def}</strong>.</p><p class="fight-summary">You <strong>${r.won?'WON':'LOST'}</strong> the fight, taking <strong>${r.damage}</strong> damage and dealing <strong>${r.dealt}</strong> damage to the enemy shinobi. You gained <strong>${r.coins} Copper</strong> and <strong>${r.xp} Experience</strong>.</p><p class="report-note">${r.killed?'Enemy killed · +1 Kill<br>':''}${r.died?'You were killed · +1 Death<br>':''}Your record: ${s.kills} Kills · ${s.deaths} Deaths</p><p class="report-note">Rival health: ${rivalState(r.id).hp} / 100 HP${rivalState(r.id).hp===0?' · Killed — recovering':''}</p><p class="report-note">You spent: 1 Stamina · Practice rival</p>`;
  action=`data-fight="${r.id}"`;disabled=s.stamina<1||s.hp<=0||rivalState(r.id).hp<=0;
 }else{
  const percent=Math.min(r.mastery,5)*20;
  const entry=(r.type==='mission'?missions:techniques).find(e=>e.id===r.id);
  body=`<div class="result-entry">${entry?entryArt(entry):''}<div><span class="result-grade">GRADE ${r.grade}</span><h3>Completed: ${escapeHTML(r.name)}</h3></div></div><p class="mastery-label">${percent===100?'Expert':'Mastery'}: ${percent}%${r.type==='mission'?' Completed':''}</p><div class="classic-progress" role="progressbar" aria-label="Mastery" aria-valuenow="${percent}" aria-valuemin="0" aria-valuemax="100"><i style="width:${percent}%"></i></div><div class="spent-gained"><div><h4>You spent:</h4><p>${r.cost} ${r.type==='mission'?'Stamina':'Spirit'}</p></div><div><h4>You gained:</h4><p>${r.xp} Experience${r.type==='mission'?'<br>'+r.coins+' Copper':r.improved?'<br>+'+r.a+' Attack · +'+r.d+' Defense':''}</p></div></div>`;
  action=`data-${r.type==='mission'?'mission':'tech'}="${r.id}"`;disabled=(r.type==='mission'?s.stamina:s.energy)<r.cost;
 }
 const repeat=r.type==='fight'?'Fight this rival again':r.type==='mission'?'Do this mission again':'Learn this jutsu again';
 const note=disabled?(r.type==='fight'?(rivalState(r.id).hp<=0?'This rival is recovering. Wait for their health to regenerate.':s.hp<=0?'Recover at the infirmary before fighting again.':'Recover stamina before fighting again.'):r.type==='mission'?'Recover stamina to repeat this mission.':'Recover spirit to repeat this action.'):'';
 const html=`<section class="classic-result ${r.type==='fight'?'battle-result':''} ${r.won===false?'result-defeat':''}" role="status" aria-live="polite" aria-atomic="true" tabindex="-1" id="action-result"><button class="result-dismiss" data-dismiss-result="true" aria-label="Dismiss result">×</button>${body}<div class="result-actions">${note?'<span>'+note+'</span>':''}<button class="classic-again" ${action} ${disabled?'disabled':''}>${repeat}</button></div></section>`;
 $('#view').insertAdjacentHTML('afterbegin',html);
}
function revealResult(){const el=$('#action-result');if(el){el.focus({preventScroll:true});el.scrollIntoView({behavior:'smooth',block:'nearest'})}}
function fight(id){
 if(busy)return;regen();const o=opponents.find(x=>x.id===id);if(!o)return;
 const rival=rivalState(id);if(rival.hp<=0){toast('This rival is recovering and cannot be attacked.');return}
 if(s.stamina<1||s.hp<=0){toast('Restore your health and stamina before fighting.');return}
 busy=true;s.stamina--;const p=power(),roll=.9+Math.random()*.2,attack=Math.round(p.a*roll),won=attack>=o.def,damage=Math.min(s.hp,27,Math.max(2,Math.round(o.atk*.3-p.d*.12+(won?2:8)))),dealt=Math.min(rival.hp,27,won?Math.max(5,Math.round(attack*.25)):Math.max(2,Math.round(attack*.08)));
 s.hp=Math.max(0,s.hp-damage);rival.hp-=dealt;rival.last=Date.now();const killed=rival.hp===0,died=s.hp===0;if(killed){s.kills++;rival.deaths=(rival.deaths||0)+1}if(died){s.deaths++;rival.kills=(rival.kills||0)+1}const reward=won?o.coins:0,xp=won?o.xp:4;
 lastResults.arena={type:'fight',id,won,killed,died,attack,damage,dealt,coins:reward,xp,base:s.atk,gear:p.ia,tech:p.ta,team:p.ca,teamCount:s.team.length+1,equipment:items.filter(i=>s.items[i.id]).map(i=>i.name),arts:techniques.filter(t=>s.tech[t.id]).map(t=>t.name+' (rank '+s.tech[t.id]+')')};
 rival[won?'losses':'wins']=(rival[won?'losses':'wins']||0)+1;s[won?'wins':'losses']++;gain(xp,reward);log((won?'Defeated ':'Lost a duel to ')+o.name+'.');if(killed)log('Killed '+o.name+' · +1 Kill.');if(died)log('Killed by '+o.name+' · +1 Death.');save();busy=false;render();revealResult();
}
function entryArt(entry){
 const layout=GAME_CATALOG.artLayouts?.[entry.artSheet],col=entry.artIndex%5,row=Math.floor(entry.artIndex/5);
 let x=col*25,y=row*50,sx=500,sy=300;
 if(layout){const xs=layout.columns||[0,307.2,614.4,921.6,1228.8,1536],ys=layout.rows||[0,1024/3,2048/3,1024],w=layout.width||1536,h=layout.height||1024,cw=xs[col+1]-xs[col],ch=ys[row+1]-ys[row];sx=w/cw*100;sy=h/ch*100;x=xs[col]/(w-cw)*100;y=ys[row]/(h-ch)*100}
 return `<span class="catalog-art" role="img" aria-label="${escapeHTML(entry.name)} illustration" style="background-image:url('assets/icons/${entry.artSheet}.webp');background-size:${sx}% ${sy}%;background-position:${x}% ${y}%"></span>`;
}
function gradeNavigation(kind){
 const entries=kind==='missions'?missions:techniques, progress=kind==='missions'?s.missions:s.tech, selected=selectedGrades[kind];
 return `<div class="grade-nav" aria-label="${kind==='missions'?'Mission':'Jutsu'} grades">${grades.map(g=>{const mastered=entries.filter(e=>e.grade===g.id&&(progress[e.id]||0)>=5).length;return `<button class="grade-tab ${selected===g.id?'selected':''} ${s.level<g.level?'grade-locked':''}" data-grade="${g.id}" aria-pressed="${selected===g.id}"><span class="grade-letter">${g.id}</span><span>${s.level<g.level?'Level '+g.level:mastered+' / 15 mastered'}</span></button>`}).join('')}</div>`;
}
function catalogHeader(kind){
 const selected=selectedGrades[kind],g=grades.find(g=>g.id===selected),entries=kind==='missions'?missions:techniques,progress=kind==='missions'?s.missions:s.tech;
 const total=entries.filter(e=>(progress[e.id]||0)>=5).length,levelLocked=s.level<g.level;
 return title(kind==='missions'?'MISSION BOARD':'JUTSU HALL',kind==='missions'?'From village errands to threats beyond the veil.':'From your first spirit art to forbidden master techniques.')+
 `<div class="catalog-overview"><span><b>90</b> ${kind==='missions'?'missions':'jutsus'} · 6 grades</span><span><b>${total}</b> / 90 mastered</span></div>`+gradeNavigation(kind)+
 `<div class="grade-heading"><div><span class="eyebrow">${levelLocked?'PREVIEW · UNLOCK AT LEVEL '+g.level:'AVAILABLE · LEVEL '+g.level+'+'}</span><h2>Grade ${selected} ${kind==='missions'?'missions':'jutsus'}</h2></div><span class="badge">15 ${kind==='missions'?'MISSIONS':'JUTSUS'}</span></div>`+
 (levelLocked?`<div class="grade-notice">Reach <strong>level ${g.level}</strong> to ${kind==='missions'?'undertake these missions':'learn these jutsus'}. You can inspect their rewards and requirements now.</div>`:'');
}
function missionView(){const grade=selectedGrades.missions;
 $('#view').innerHTML=catalogHeader('missions')+`<div class="catalog-list">${missions.filter(m=>m.grade===grade).map(m=>{const done=s.missions[m.id]||0,mastered=done>=5,reward=Math.round(m.coins*(mastered?1.2:1)),locked=s.level<m.level,short=s.stamina<m.cost;return `<article class="catalog-row ${locked?'entry-locked':''}">${entryArt(m)}<div class="catalog-content"><div class="eyebrow">GRADE ${m.grade} · MISSION ${String(m.artIndex+1).padStart(2,'0')}</div><h3>${m.name}</h3><p>${m.desc}</p><div class="catalog-mastery"><span>${mastered?'Expert':'Mastery'}: ${Math.min(done,5)*20}%${mastered?' · +20% copper':''}</span><div class="classic-progress"><i style="width:${Math.min(done,5)*20}%"></i></div></div></div><div class="catalog-action"><div class="catalog-rewards"><span>REWARD</span><b>${fmt(reward)} Copper</b><b>${m.xp} Experience</b></div><div class="catalog-requirement">${m.cost} Stamina · Level ${m.level}</div><button class="classic-again" data-mission="${m.id}" ${locked||short?'disabled':''}>${locked?'Level '+m.level+' required':short?'Need '+m.cost+' stamina':'Do mission'}</button></div></article>`}).join('')}</div><div class="combat-note">Complete a mission five times to reach Expert mastery and earn 20% extra copper on future runs. Stamina regenerates by 1 each minute.</div>`;
}
function techView(){const grade=selectedGrades.techniques;
 $('#view').innerHTML=catalogHeader('techniques')+`<div class="catalog-list">${techniques.filter(t=>t.grade===grade).map(t=>{const n=s.tech[t.id]||0,locked=s.level<t.level,short=s.energy<t.cost;return `<article class="catalog-row ${locked?'entry-locked':''}">${entryArt(t)}<div class="catalog-content"><div class="eyebrow">GRADE ${t.grade} · ${t.type.toUpperCase()}</div><h3>${t.name}</h3><p>${t.desc}</p><div class="catalog-mastery"><span>${n>=5?'Expert':'Mastery'}: ${Math.min(n,5)*20}% · ${n} / 5</span><div class="classic-progress"><i style="width:${Math.min(n,5)*20}%"></i></div></div></div><div class="catalog-action"><div class="catalog-rewards"><span>${n>=5?'MASTERED BONUS':'PER MASTERY RANK'}</span><b>+${n>=5?t.a*5:t.a} Attack · +${n>=5?t.d*5:t.d} Defense</b><b>${t.xp} Experience</b></div><div class="catalog-requirement">${t.cost} Spirit · Level ${t.level}</div><button class="classic-again" data-tech="${t.id}" ${locked||short?'disabled':''}>${locked?'Level '+t.level+' required':short?'Need '+t.cost+' spirit':n>=5?'Practice jutsu':'Learn jutsu'}</button></div></article>`}).join('')}</div><div class="combat-note">Each mastery rank adds the listed attack and defense to every fight. After rank 5, practice still grants Experience but no additional stats. Higher grades unlock at levels 3, 5, 8, 12, and 16.</div>`;
}
function equipmentView(){$('#view').innerHTML=title('THE ARMORY','One trusted piece of gear can turn a battle.')+`<div class="grid equipment-grid">${items.map(i=>`<article class="card">${uiIcon({blade:11,coat:12,needles:13,charm:14}[i.id],'equipment-art')}<div class="eyebrow">${s.items[i.id]?'EQUIPPED':'FIELD EQUIPMENT'}</div><h3>${i.name}</h3><p>${i.desc}</p><div class="cost gear-stats">${uiIcon(0)} +${i.a} attack &nbsp; ${uiIcon(15)} +${i.d} defense</div><button class="${s.items[i.id]?'outline':'gold'}" data-buy="${i.id}" ${s.items[i.id]||s.coins<i.price?'disabled':''}>${s.items[i.id]?'✓ Owned & equipped':'Buy · '+fmt(i.price)+' copper'}</button></article>`).join('')}</div><div class="combat-note">Purchased gear is automatically equipped. Each unique item contributes once. There are no real-money purchases.</div>`}
function teamView(){$('#view').innerHTML=title('YOUR INNER CIRCLE','Choose the shinobi who will stand beside you.')+`<div class="team-summary"><span>${uiIcon(4)}<b>${s.team.length} / 3</b> companions recruited</span><span>30% of their power joins yours</span></div><div class="grid team-grid">${companions.map(c=>`<article class="card team-card ${s.team.includes(c.id)?'recruited':''}"><div class="companion-portrait face f${c.face}"><span class="companion-role">${c.role}</span>${s.team.includes(c.id)?'<span class="in-team">IN YOUR TEAM</span>':''}</div><div class="companion-body"><h3>${c.name}</h3><div class="companion-stats"><span>${uiIcon(0)}<b>${c.a}</b> Attack</span><span>${uiIcon(15)}<b>${c.d}</b> Defense</span></div><p>Team bonus: <strong>+${Math.round(c.a*.3)} attack</strong>, <strong>+${Math.round(c.d*.3)} defense</strong>, +5 maximum spirit.</p><button class="${s.team.includes(c.id)?'outline':'gold'}" data-recruit="${c.id}" ${s.team.includes(c.id)||s.coins<c.price?'disabled':''}>${s.team.includes(c.id)?'Recruited':uiIcon(6)+'Recruit · '+fmt(c.price)}</button></div></article>`).join('')}</div><div class="combat-note">Your companions support every fight. Recruit them once to permanently add their bonuses to your shinobi.</div>`}
function profileView(){const p=power();$('#view').innerHTML=title('YOUR LEGEND',rank()+' of Hollow Falls · Level '+s.level)+`<div class="grid"><article class="card"><div class="eyebrow">IDENTITY</div><h3>Make your name</h3><label for="name-input">Shinobi name</label><input id="name-input" maxlength="20" value="${escapeHTML(s.name)}"><button class="outline" id="rename">Save name</button><div class="cost">${s.wins} victories · ${s.losses} defeats<br>${s.kills} Kills · ${s.deaths} Deaths<br>${Object.keys(s.missions).reduce((n,k)=>n+s.missions[k],0)} missions completed</div></article><article class="card"><div class="eyebrow">${s.points} POINTS AVAILABLE</div><h3>Develop your strengths</h3><p>Earn 3 points each level. Each point adds 5 to a base stat.</p><div class="stat-line"><span>Attack <b>${s.atk}</b></span><button data-stat="atk" ${s.points?'':'disabled'}>+ 5</button></div><div class="stat-line"><span>Defense <b>${s.def}</b></span><button data-stat="def" ${s.points?'':'disabled'}>+ 5</button></div></article><article class="card"><div class="eyebrow">COMBAT BREAKDOWN</div><h3>Every edge, accounted for</h3>${[['Base',s.atk,s.def],['Equipment',p.ia,p.id],['Techniques',p.ta,p.td],['Team',p.ca,p.cd],['Total',p.a,p.d]].map(([n,a,d])=>`<div class="stat-line"><span>${n}</span><span class="stat-icons">${a} ${uiIcon(0)} &nbsp; ${d} ${uiIcon(15)}</span></div>`).join('')}</article><article class="card"><div class="eyebrow">VILLAGE SERVICES</div><h3>Recover & regroup</h3><p>Natural recovery each minute: 2 health, 3 spirit, and 1 stamina. Or spend copper to recover now.</p><button class="outline" data-action="heal">Infirmary · 75 copper</button><br><br><button class="outline" data-action="rest">Full rest · 150 copper</button><br><br><button class="outline" data-action="bank">Open your bank</button></article></div>`;$('#rename').onclick=()=>{const v=$('#name-input').value.trim();if(!v)return toast('Enter a name first.');s.name=v;save();render();toast('Your name has been saved.')}}
function bank(){open(`<div class="eyebrow">HOLLOW FALLS TREASURY</div><h2>Your copper, kept safe.</h2><p>Wallet: ${fmt(s.coins)} · Bank: ${fmt(s.bank)}</p><label for="amount">Amount</label><input id="amount" type="number" min="1" step="1" value="100"><div class="row"><button class="gold" id="deposit">Deposit</button><button class="outline" id="withdraw">Withdraw</button></div>`);['deposit','withdraw'].forEach(action=>$('#'+action).onclick=()=>{const amount=Number($('#amount').value);if(!Number.isSafeInteger(amount)||amount<1)return toast('Enter a positive whole number.');const source=action==='deposit'?'coins':'bank',dest=action==='deposit'?'bank':'coins';if(s[source]<amount)return toast('Not enough copper.');s[source]-=amount;s[dest]+=amount;save();render();bank();toast(action==='deposit'?'Copper deposited.':'Copper withdrawn.')})}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.grade){if(selectedGrades[tab]&&grades.some(g=>g.id===b.dataset.grade)){selectedGrades[tab]=b.dataset.grade;render()}return}if(b.dataset.dismissResult){delete lastResults[tab];render();return}if(b.dataset.tab){tab=b.dataset.tab;render();return}if(b.dataset.filter){filter=b.dataset.filter;render();return}if(b.dataset.fight!==undefined){fight(Number(b.dataset.fight));return}if(b.dataset.mission){const m=missions.find(x=>x.id===b.dataset.mission);if(!m||s.stamina<m.cost||s.level<m.level)return;s.stamina-=m.cost;const reward=Math.round(m.coins*((s.missions[m.id]||0)>=5?1.2:1));s.missions[m.id]=(s.missions[m.id]||0)+1;gain(m.xp,reward);log('Completed '+m.name+'.');lastResults.missions={type:'mission',id:m.id,grade:m.grade,name:m.name,cost:m.cost,xp:m.xp,coins:reward,mastery:s.missions[m.id]}}else if(b.dataset.tech){const t=techniques.find(x=>x.id===b.dataset.tech);if(!t||s.energy<t.cost||s.level<(t.level||1))return;const improved=(s.tech[t.id]||0)<5;s.energy-=t.cost;s.tech[t.id]=Math.min(5,(s.tech[t.id]||0)+1);gain(t.xp,0);log(t.name+(improved?' advanced to rank '+s.tech[t.id]+'.':' practiced at expert mastery.'));lastResults.techniques={type:'tech',id:t.id,grade:t.grade,name:t.name,cost:t.cost,xp:t.xp,mastery:s.tech[t.id],improved,a:t.a,d:t.d}}else if(b.dataset.buy){const i=items.find(x=>x.id===b.dataset.buy);if(s.items[i.id]||s.coins<i.price)return;s.coins-=i.price;s.items[i.id]=true;log('Equipped '+i.name+'.');toast(i.name+' equipped')}else if(b.dataset.recruit){const c=companions.find(x=>x.id===b.dataset.recruit);if(s.team.includes(c.id)||s.coins<c.price)return;s.coins-=c.price;s.team.push(c.id);log(c.name+' joined your team.');toast('A new companion joins your journey.')}else if(b.dataset.stat){if(s.points<=0)return;s.points--;s[b.dataset.stat]+=5;toast('Base '+(b.dataset.stat==='atk'?'attack':'defense')+' increased by 5')}else if(b.dataset.action){const a=b.dataset.action;if(a==='bank'){bank();return}const cost=a==='heal'?75:150;if(a==='heal'&&s.hp>=maxHealth())return toast('Your health is already full.');if(a==='rest'&&s.hp===maxHealth()&&s.energy===maxEnergy()&&s.stamina===maxStamina())return toast('You are fully rested.');if(s.coins<cost)return toast('Not enough copper. Resources also recover over time.');s.coins-=cost;s.hp=maxHealth();if(a==='rest'){s.energy=Math.max(s.energy,maxEnergy());s.stamina=maxStamina()}log(a==='rest'?'Rested at the village inn.':'Recovered at the infirmary.');toast(a==='rest'?'Fully rested. Ready for the road.':'Health restored.')}else{return}save();render();if(b.dataset.mission||b.dataset.tech)revealResult()});
$('#close-modal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});$('#guide').onclick=()=>open(`<div class="eyebrow">WELCOME TO HOLLOW FALLS</div><h2>Your first steps</h2><p>1. Spend your 3 starting stat points in <b>Profile</b>.<br>2. Learn jutsus using spirit. Browse 15 jutsus in each grade from E to S.<br>3. Buy equipment and recruit companions with copper.<br>4. Challenge rivals in the arena. Each fight costs 1 stamina. Damage is capped at 27 HP per fighter. A rival at 0 HP must recover before you can attack again.<br>5. Complete missions using stamina for copper and XP. Grades E, D, C, B, A, and S unlock at levels 1, 3, 5, 8, 12, and 16. Leveling up refills your resources and grants 3 stat points.</p><h3>How battles work</h3><p>Your attack is your base stat + gear + learned techniques + 30% of companion attack. A ±10% variation is applied. Meet or exceed the rival’s defense to win. Your defense reduces incoming damage.</p><p>This version uses AI rivals and saves on this browser. It has no player accounts, live PvP, or cross-device saves. Combat rules are an original approximation of classic social RPG mechanics.</p>`);setInterval(()=>{regen();render()},60000);render();
